# -*- coding: utf-8 -*-
TIER2_HEAD = r'<b>【 แบบที่ 2 ▸ พื้นฐาน · กระชับ · กฎของโคไซน์ที่มุม $B$ แล้วอ่านความสูงจากสามเหลี่ยมมุมฉาก (law of cosines, then right-triangle height) 】</b>'
TIER2 = [
    r'🎯 <b>เหมาะกับ</b> เด็กปานกลางถึงเก่ง · แปลคำว่า “แนวตรงจาก $A$ ที่ตั้งฉากกับ $BC$” เป็นความสูงที่คู่กับฐาน $BC$ ได้เอง และใช้กฎของโคไซน์คู่กับอัตลักษณ์พีทาโกรัสได้คล่อง',
    r'<b>ขั้นที่ 1:</b> ให้ $D$ เป็นจุดบน $BC$ ที่ทางเดินไปพบพอดี ⇒ ความยาวที่โจทย์ถามคือ $AD$ ซึ่งก็คือความสูงของสามเหลี่ยม $ABC$ เมื่อใช้ $BC$ เป็นฐาน',
    r'⇒ สามเหลี่ยม $ABD$ มีมุมฉากที่ $D$ โดยมี $AB = 13$ เป็นด้านตรงข้ามมุมฉาก และ $AD$ อยู่ตรงข้ามมุม $B$',
    r'<b>ขั้นที่ 2:</b> ใช้กฎของโคไซน์ที่มุม $B$ · ด้านที่ประกบมุม $B$ คือ $AB = 13$ กับ $BC = 14$ ส่วนด้านตรงข้ามมุม $B$ คือ $CA = 15$',
    r'⇒ $\cos B = \dfrac{13^{2} + 14^{2} - 15^{2}}{2(13)(14)} = \dfrac{169 + 196 - 225}{364} = \dfrac{140}{364} = \dfrac{5}{13}$',
    r'<b>ขั้นที่ 3:</b> เปลี่ยนเป็นไซน์ด้วย $\sin^{2}B + \cos^{2}B = 1$ · มุม $B$ เป็นมุมภายในของรูปสามเหลี่ยมจึงได้ $\sin B > 0$ หยิบรากบวกได้ทันที',
    r'⇒ $\sin^{2}B = 1 - \left(\dfrac{5}{13}\right)^{2} = \dfrac{169 - 25}{169} = \dfrac{144}{169}$ ⇒ $\sin B = \dfrac{12}{13}$',
    r'<b>ขั้นที่ 4:</b> อ่าน $AD$ ออกจากสามเหลี่ยมมุมฉาก $ABD$ ด้วย $\sin B = \dfrac{AD}{AB}$ แล้วย้ายข้าง',
    r'⇒ $AD = AB\sin B = 13 \times \dfrac{12}{13} = 12$ ⇒ ทางเดินยาว $12$ เมตร · ตรวจขนาดเร็ว ๆ ได้ว่า $AD$ เป็นขาของรูปที่มีด้านตรงข้ามมุมฉากยาว $13$ จึงต้องน้อยกว่า $13$ จริง',
]
TIER3_HEAD = r'<b>【 แบบที่ 3 ▸ ⚡ ประยุกต์ · ประกบสามเหลี่ยมมุมฉากสองรูป (Pythagorean decomposition) 】</b>'
TIER3 = [
    r'⚡ <b>เหมาะกับ</b> เด็กที่พื้นฐานคณิตดี · มองออกว่าเส้นตั้งฉากผ่ารูปใหญ่เป็นสามเหลี่ยมมุมฉากสองรูปที่ใช้ความสูงเส้นเดียวกันร่วมกัน แล้วตั้งสมการเดียวจบด้วยพีทาโกรัส',
    r'<b>ขั้นที่ 1:</b> ให้เท้าของเส้นตั้งฉากแบ่ง $BC$ เป็นสองท่อน ยาว $x$ กับ $14 - x$ โดยวัด $x$ จากจุด $B$',
    r'⇒ ความสูงเป็นขาของทั้งสองรูป จึงเขียนกำลังสองของความสูงได้สองทาง คือ $13^{2} - x^{2}$ กับ $15^{2} - (14 - x)^{2}$',
    r'<b>ขั้นที่ 2:</b> จับสองก้อนนั้นเท่ากัน ⇒ $169 - x^{2} = 225 - \left(196 - 28x + x^{2}\right) = 29 + 28x - x^{2}$',
    r'⇒ พจน์ $x^{2}$ ตัดกันทั้งสองข้าง เหลือสมการเชิงเส้น ⇒ $28x = 140$ ⇒ $x = 5$',
    r'<b>ขั้นที่ 3:</b> แทน $x = 5$ กลับเข้าความสูง ⇒ ความสูง $= \sqrt{169 - 25} = \sqrt{144} = 12$ เมตร',
    r'⇒ อ่านโครงสร้างได้เลยว่าสองท่อนคือ $5$ กับ $9$ ⇒ รูป $13$-$14$-$15$ ก็คือชุด $5$-$12$-$13$ ประกบกับชุด $9$-$12$-$15$ ที่ความสูงร่วม $12$',
    r'<b>ข้อต่าง:</b> ไม่ต้องแตะกฎของโคไซน์ ไม่ต้องหา $\cos B$ หรือ $\sin B$ และไม่ต้องใช้เฮรอนหรือรู้พื้นที่เลย ต่างจากแบบที่ 1–2 ที่ต้องเดินผ่านค่ามุมก่อนจึงจะถอดความสูงออกมาได้',
]
